r = \sqrt{x^2 + y^2} = \sqrt{1+3} = \sqrt{4} = 2
\cos\theta = \frac{x}{r} = \frac{1}{2}
\sin\theta = \frac{y}{r} = \frac{-\sqrt{3}}{2}
زاوية الاسناد = \frac{\pi}{3}
وتقع في الربع الرابع (+, -)
arg(Z) = 2\pi - \frac{\pi}{3} = \frac{5\pi}{3}
\therefore \sqrt{Z} = \sqrt{2} (\cos \frac{5\pi}{3} + i \sin \frac{5\pi}{3})^{1/2}
= \sqrt{2} (\cos \frac{5\pi/3 + 2k\pi}{2} + i \sin \frac{5\pi/3 + 2k\pi}{2})
عندما K = 0, 1
عندما K = 0 \Rightarrow Z_1 = \sqrt{2} (\cos \frac{5\pi}{6} + i \sin \frac{5\pi}{6})
= \sqrt{2} (-\frac{\sqrt{3}}{2} + \frac{1}{2}i)
= -\frac{\sqrt{3}}{\sqrt{2}} + \frac{1}{\sqrt{2}}i
عندما K = 1 \Rightarrow Z_2 = \sqrt{2} (\cos \frac{11\pi}{6} + i \sin \frac{11\pi}{6})
= \sqrt{2} (\frac{\sqrt{3}}{2} - \frac{1}{2}i)
= \frac{\sqrt{3}}{\sqrt{2}} - \frac{1}{\sqrt{2}}i
\therefore S = \{-\frac{\sqrt{3}}{\sqrt{2}} + \frac{1}{\sqrt{2}}i, \frac{\sqrt{3}}{\sqrt{2}} - \frac{1}{\sqrt{2}}i\}

